def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    if budget <= 0:
        return 0.0

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if not alive_opponents:
        base = DAILY_SALARY * 0.28
        if hp <= 2 or no_water_days >= 1:
            base = DAILY_SALARY * 0.75
        return float(max(0.0, min(budget, base)))

    prev_bids = []
    distressed_opponents = 0
    desperate_opponents = 0
    rich_aggressive = 0

    for opp in alive_opponents:
        prev = opp.get('previous_trace') or {}
        bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(float(bid))
        opp_hp = float(opp.get('hp', 0))
        opp_budget = float(opp.get('budget', 0))
        opp_nwd = int(opp.get('no_water_days', 0))
        if opp_hp <= 3 or opp_nwd >= 1:
            distressed_opponents += 1
        if opp_hp <= 2 or opp_nwd >= 2:
            desperate_opponents += 1
        if opp_budget >= DAILY_SALARY * 6:
            rich_aggressive += 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    scarcity = (supply - 15.0) / 10.0
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0
    low_supply = 1.0 - scarcity

    base = DAILY_SALARY * (0.34 + 0.18 * low_supply)

    if highest_prev >= 100:
        base = min(base, DAILY_SALARY * 0.38)
    elif highest_prev >= 80:
        base = min(base, DAILY_SALARY * 0.45)
    elif highest_prev > 0:
        base = max(base, min(DAILY_SALARY * 0.62, avg_prev * 0.78 + 2.0))

    if distressed_opponents >= 2:
        base *= 0.92
    if desperate_opponents >= 1 and hp >= 4:
        base *= 0.9
    if rich_aggressive >= 2 and hp >= 4:
        base *= 0.95

    if hp <= 2:
        base = max(base, DAILY_SALARY * 0.96)
    elif hp <= 4 or no_water_days >= 1:
        base = max(base, DAILY_SALARY * (0.72 + 0.12 * low_supply))
    elif hp >= 8 and budget < DAILY_SALARY * 4:
        base = min(base, DAILY_SALARY * 0.42)

    if day >= 8:
        if hp <= 5:
            base = max(base, DAILY_SALARY * 0.82)
        else:
            base = max(base, DAILY_SALARY * 0.46)

    if budget < DAILY_SALARY * 2:
        base = min(base, budget * 0.72 + 4.0)

    bid = max(0.0, min(budget, base))
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    supply = day_context['supply']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], 20.0)

    avg_prev_bid = 0
    count = 0
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            avg_prev_bid += prev['bid']
            count += 1

    if count > 0:
        avg_prev_bid /= count

    target_bid = avg_prev_bid * 1.05 if avg_prev_bid > 0 else 35.0

    if my_status['hp'] < 4:
        target_bid = max(target_bid, 55.0)

    if supply < WATER_REQ * 2:
        target_bid = max(target_bid, 45.0)

    return min(my_status['budget'], float(target_bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    alive_opponents = {oid: o for oid, o in opponents_status.items() if o['alive']}

    # Determine yesterday's max bid among alive opponents
    max_prev_bid = None
    for opp in alive_opponents.values():
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None and prev.get('status') != 'error':
            bid = prev['bid']
            if max_prev_bid is None or bid > max_prev_bid:
                max_prev_bid = bid

    # Base strategy based on current hp
    hp = my_status['hp']
    budget = my_status['budget']

    # Urgency levels
    if hp <= 2:
        # Critical need water
        if max_prev_bid is not None:
            target = max_prev_bid + 5.0
        else:
            target = DAILY_SALARY * 0.95  # 133
        return min(budget, target)
    elif hp <= 5:
        # Moderate need
        if max_prev_bid is not None:
            target = max_prev_bid + 2.5
        else:
            target = DAILY_SALARY * 0.85  # 119
        return min(budget, target)
    else:
        # Healthy, conserve
        if max_prev_bid is not None:
            target = max_prev_bid - 2.5
            # Ensure positive and reasonable
            if target < DAILY_SALARY * 0.5:
                target = DAILY_SALARY * 0.55
        else:
            target = DAILY_SALARY * 0.65  # 91
        return min(budget, max(1.0, target))
